// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *TaxJurisdiction) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, TaxJurisdictionTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (code)`,
		fmt.Sprintf("%s$Tax_Jurisdiction$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (report_to_jurisdiction)`,
		fmt.Sprintf("%s$Tax_Jurisdiction$report_to", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index report_to: %w", err)
	}
	var keys []sift.Key
	for _, spec := range taxJurisdictionSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, TaxJurisdictionTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, TaxJurisdictionTableName, keys)
}

// taxJurisdictionSIFTSpecs are the table's keys with sum_index_fields
func taxJurisdictionSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *TaxJurisdiction) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, TaxJurisdictionTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range taxJurisdictionSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, TaxJurisdictionTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: TaxJurisdictionTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, TaxJurisdictionTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

