	var adjust_for_payment_discountBool sql.NullBool

	err := t.exec().QueryRow(query, args...).Scan(
		&codeNull,
		&descriptionNull,
		&tax_account_salesNull,
		&tax_account_purchasesNull,
		&report_to_jurisdictionNull,
		&unreal_tax_acc_salesNull,
		&unreal_tax_acc_purchasesNull,
		&reverse_charge_purchasesNull,
		&unreal_rev_charge_purchNull,
		&unrealized_tax_typeInt,
		&calculate_tax_on_taxBool,
		&adjust_for_payment_discountBool,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			return false
		}
		fmt.Printf("Error: Failed to find first Tax_Jurisdiction: %v\n", err)
		return false
	}

	// Populate fields
	t.Code = types.NewCode(codeNull.String)
	t.Description = types.NewText(descriptionNull.String)
	t.Tax_account_sales = types.NewCode(tax_account_salesNull.String)
	t.Tax_account_purchases = types.NewCode(tax_account_purchasesNull.String)
	t.Report_to_jurisdiction = types.NewCode(report_to_jurisdictionNull.String)
	t.Unreal_tax_acc_sales = types.NewCode(unreal_tax_acc_salesNull.String)
